/**
 * Syntax tree of the FML subset generated by CinderMed.
 *
 * Contract (docs/specification.md, "Generator contract"): the generator builds ONLY these nodes and
 * hands them to the printer (fml-print.ts). Every construct here is covered by the checks of
 * fixtures/fml-examples (grammar mapping.g4 @8bb04b4, HL7 engine org.hl7.fhir.core 7.0.5, Bundle
 * validation). Adding a node means first adding a golden case that covers it.
 *
 * Names are branded types: they can only be obtained from the constructors at the end of this file,
 * which reject values the grammar or the HL7 parser do not accept.
 */

// ---------------------------------------------------------------- names

/** Group or map name: grammar token ID, `^[A-Za-z][A-Za-z0-9]*$` (no `_`). */
export type GroupName = string & { readonly __brand: "GroupName" };
/** Variable, alias, parameter or element: token IDENTIFIER, `^[A-Za-z_][A-Za-z0-9_]*$`. */
export type Identifier = string & { readonly __brand: "Identifier" };
/** Rule name, printed between double quotes: `^[A-Za-z0-9_.-]+$` (e.g. `R-006-1`, `Encounter0-id`). */
export type RuleName = string & { readonly __brand: "RuleName" };

// ---------------------------------------------------------------- map

export interface StructureMapAst {
  /** Canonical URL; printed between double quotes. */
  readonly url: string;
  /** Printed between backticks: the only form accepted by both the grammar and the HL7 parser. */
  readonly name: GroupName;
  readonly uses: readonly Use[];
  /** The first group is the table's main group. */
  readonly groups: readonly Group[];
}

export type UseMode = "source" | "target" | "produced";

export interface Use {
  readonly url: string;
  readonly alias: Identifier;
  readonly mode: UseMode;
}

export interface Group {
  readonly name: GroupName;
  /** The grammar requires at least two parameters. */
  readonly params: readonly [Param, Param, ...Param[]];
  readonly rules: readonly Rule[];
  /** Comment printed as `//` lines before the group. */
  readonly comment?: string;
}

export interface Param {
  readonly mode: "source" | "target";
  readonly name: Identifier;
  readonly type?: Identifier;
}

// ---------------------------------------------------------------- rules

export interface Rule {
  readonly name: RuleName;
  /** Printed as `//` lines before the rule (never `///`: rejected by the HL7 parser). */
  readonly comment?: string;
  /** Always exactly one source. */
  readonly source: Source;
  /** Empty means a rule without `->` (e.g. `src then Group(src, res)`). */
  readonly targets: readonly Target[];
  readonly then?: Then;
}

export interface Source {
  /** E.g. `src`. */
  readonly context: Identifier;
  /** E.g. `AdmissionDate` in `src.AdmissionDate`. */
  readonly element?: Identifier;
  /** `as v`. */
  readonly alias?: Identifier;
  /** `where ( ... )`. */
  readonly where?: Expr;
}

/** Element targets only: `context.element [= transform] [as alias]`. */
export interface Target {
  readonly context: Identifier;
  readonly element: Identifier;
  readonly transform?: Transform;
  readonly alias?: Identifier;
}

/** Constant of a transform or of a FHIRPath comparison. */
export type Literal = string | number | boolean;

export type Transform =
  /** `'final'`, `3`, `true` */
  | { readonly kind: "literal"; readonly value: Literal }
  /** `= v` */
  | { readonly kind: "copy"; readonly variable: Identifier }
  /** `create('Encounter')` */
  | { readonly kind: "create"; readonly type: Identifier }
  /** Coding: `c(system, code[, display])` */
  | {
      readonly kind: "c";
      readonly system: string;
      readonly code: string;
      readonly display?: string;
    }
  /** CodeableConcept: `cc(system, code[, display])` */
  | {
      readonly kind: "cc";
      readonly system: string;
      readonly code: string;
      readonly display?: string;
    }
  /** `evaluate(i, 'Patient/' + $this)` */
  | { readonly kind: "evaluate"; readonly variable: Identifier; readonly expression: Expr };

export type Then =
  /** `then { ... }` */
  | { readonly kind: "rules"; readonly rules: readonly Rule[] }
  /** `then Group(a, b)` */
  | {
      readonly kind: "invoke";
      readonly group: GroupName;
      readonly args: readonly [Identifier, ...Identifier[]];
    };

// ---------------------------------------------------------------- FHIRPath (structured subset)

/**
 * Generated FHIRPath expressions. Columns are always printed with the `$this.` prefix: a name
 * starting with a capital letter, at the start of an expression, would be read as a type.
 */
export type Expr =
  /** `$this.col.exists()` */
  | { readonly kind: "exists"; readonly column: Identifier }
  /** `$this.col.where($this = a or ...).exists()` */
  | {
      readonly kind: "anyOf";
      readonly column: Identifier;
      readonly values: readonly [Literal, ...Literal[]];
    }
  /** `$this.col.where($this = a or ...).empty()` */
  | {
      readonly kind: "noneOf";
      readonly column: Identifier;
      readonly values: readonly [Literal, ...Literal[]];
    }
  /** `$this = 'v'` (filter on the alias) */
  | { readonly kind: "thisEquals"; readonly value: Literal }
  | { readonly kind: "and" | "or"; readonly args: readonly [Expr, Expr, ...Expr[]] }
  /** `(expr).not()` */
  | { readonly kind: "not"; readonly arg: Expr }
  /** `'Patient/' + $this` */
  | { readonly kind: "prefixThis"; readonly prefix: string }
  /** Expert expression (D6) only; inserted as is, still checked by the grammar and the engine. */
  | { readonly kind: "raw"; readonly text: string };

// ---------------------------------------------------------------- checked constructors

const patterns = {
  group: /^[A-Za-z][A-Za-z0-9]*$/,
  identifier: /^[A-Za-z_][A-Za-z0-9_]*$/,
  rule: /^[A-Za-z0-9_.-]+$/,
};

/**
 * Words the official grammar (mapping.g4 @8bb04b4) does NOT accept as an element or variable name.
 * Checked on 9 November 2026 against 16 reserved words: the others (source, target, group, first,
 * last, check, where, map, uses, alias, prefix, extends) are accepted by the grammar and the HL7
 * parser without delimiters. Backticks are no way out: the HL7 parser keeps them in the name.
 */
export const RESERVED_WORDS: ReadonlySet<string> = new Set(["share", "default", "log", "then"]);

/** A value rejected by a name constructor. */
export class FmlNameError extends Error {
  override readonly name = "FmlNameError";
}

function checkName(kind: string, value: string, pattern: RegExp): void {
  if (!pattern.test(value)) throw new FmlNameError(`${kind} is not valid in FML: "${value}"`);
  if (RESERVED_WORDS.has(value)) {
    throw new FmlNameError(`${kind} is an FML reserved word: "${value}"`);
  }
}

export function groupName(value: string): GroupName {
  checkName("Group name", value, patterns.group);
  return value as GroupName;
}

export function ident(value: string): Identifier {
  checkName("Identifier", value, patterns.identifier);
  return value as Identifier;
}

export function ruleName(value: string): RuleName {
  if (!patterns.rule.test(value))
    throw new FmlNameError(`Rule name is not valid in FML: "${value}"`);
  return value as RuleName;
}
